TOKEN = re.compile(r"[a-z0-9][a-z0-9\-]*")   # hyphens stay INSIDE a term

def idf(self, term):
    n = self.df.get(term, 0)
    return math.log(1 + (self.N - n + 0.5) / (n + 0.5))

def score(self, query, doc_i):
    s = 0.0
    norm = K1 * (1 - B + B * self.lens[doc_i] / self.avgdl)   # length
    for t in tokenize(query):
        f = self.tf[doc_i].get(t, 0)
        if f:
            s += self.idf(t) * (f * (K1 + 1)) / (f + norm)    # saturating
    return s

def rrf(rankings, k=RRF_K):            # RRF_K = 60
    """rankings: ranked id lists (best first) -> fused {id: score}."""
    fused = {}
    for ranked in rankings:
        for rank, pid in enumerate(ranked, 1):
            fused[pid] = fused.get(pid, 0.0) + 1.0 / (k + rank)
    return fused


